<?php
declare(strict_types=1);
use CoreCMS\Core\Url;
use CoreCMS\Modules\HairSalon\HairSalonManager;
require_once dirname(__DIR__).'/Admin/HairSalonManager.php';
return static function(PDO $db,array $params,array $request,array $module):string{
 $m=new HairSalonManager($db);$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$base=Url::to('/salon');$services=$m->services(true);$staff=$m->staff(true);
 $html='<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuaför ve Güzellik Salonu</title><meta name="description" content="Hizmetlerimizi keşfedin, uzman ekibimizi tanıyın ve online randevu alın."><link rel="stylesheet" href="'.Url::to('/modules/hair-salon/assets/css/hair-salon.css').'"></head><body class="hs-site"><header class="hs-header"><a class="hs-brand" href="'.$base.'">ATELIER<span>.</span></a><nav><a href="'.$base.'">Hizmetler</a><a href="#ekibimiz">Ekibimiz</a><a class="hs-nav-cta" href="'.$base.'/randevu">Randevu al</a></nav></header><main class="hs-container"><section class="hs-hero"><span>GÜZELLİK, KENDİNİZE AYIRDIĞINIZ ZAMANDIR</span><h1>Kendinizin en iyi<br><em>haliyle tanışın.</em></h1><p>Uzman dokunuşlar, kişisel bakım ve size özel deneyimler.</p><a class="hs-button" href="'.$base.'/randevu">Randevunuzu oluşturun</a></section><section class="hs-section"><div class="hs-heading"><div><span>HİZMET MENÜSÜ</span><h2>Size özel bakım</h2></div><small>'.count($services).' hizmet</small></div><div class="hs-service-grid">';
 foreach($services as $s)$html.='<article class="hs-service">'.($s['image_url']?'<img src="'.$e($s['image_url']).'" alt="'.$e($s['name']).'" loading="lazy">':'<div class="hs-service-placeholder">ATELIER</div>').'<div class="hs-service-body"><small>'.$e($s['category']).' · '.$e($s['duration_minutes']).' dk</small><h3>'.$e($s['name']).'</h3><p>'.$e($s['description']).'</p><div><strong>'.number_format((float)$s['price'],0,',','.').' '.$e($s['currency']).'</strong><a href="'.$base.'/randevu?service_id='.(int)$s['id'].'">Randevu al →</a></div></div></article>';
 $html.='</div></section><section class="hs-section" id="ekibimiz"><div class="hs-heading"><div><span>UZMAN EKİBİMİZ</span><h2>Güvenli ellerdesiniz</h2></div></div><div class="hs-staff-grid">';
 foreach($staff as $person)$html.='<article>'.($person['photo_url']?'<img src="'.$e($person['photo_url']).'" alt="'.$e($person['name']).'">':'<div class="hs-avatar">'.mb_strtoupper(mb_substr($person['name'],0,1)).'</div>').'<h3>'.$e($person['name']).'</h3><p>'.$e($person['title']).'</p></article>';
 $html.='</div></section><section class="hs-cta"><h2>Kendinize bir iyilik yapın.</h2><p>Size uygun hizmeti ve zamanı seçerek hemen randevu talebi oluşturun.</p><a class="hs-button" href="'.$base.'/randevu">Online randevu</a></section></main><footer class="hs-footer">ATELIER. · '.date('Y').'</footer></body></html>';return $html;
};
